<?php
namespace App\Http\Controllers;
use App\Services\{CadenceEmail,CadenceEmailTransport,QueueRouting,QueueDiagnostic,VoicePersonalization,VoiceLab};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class CadenceImpactController extends Controller {
 private function campaign(Request $r,int $id):object {abort_unless($r->user()->voice_role==='admin'&&$r->user()->voice_workspace_id,403);return DB::table('voice_campaigns')->where('workspace_id',$r->user()->voice_workspace_id)->where('id',$id)->firstOrFail();}
 public function show(Request $r,int $id){
  $c=$this->campaign($r,$id);$w=$c->workspace_id;$s=json_decode($c->settings,true);$email=DB::table('voice_email_settings')->where('campaign_id',$id)->first();$checks=[];
  $add=function($key,$ok,$title,$detail)use(&$checks){$checks[]=['key'=>$key,'status'=>$ok?'ok':'attention','title'=>$title,'detail'=>$detail];};
  $add('campaign',$c->status==='testing','Cadência habilitada','A habilitação e os horários continuam necessários para o teste real.');
  $queues=QueueRouting::forCampaign($w,$id)->get();$diagnostics=[];foreach($queues->take(5)as $q)$diagnostics[]=app(QueueDiagnostic::class)->inspect($w,$q->id);
  $add('queues',$queues->count()>0,'Fila e atendentes','A discagem automática exige fila habilitada e atendente disponível. Consulte os impedimentos abaixo.');
  $contacts=DB::table('voice_contacts as c')->join('voice_members as m','m.contact_id','=','c.id')->where('m.campaign_id',$id)->where('c.workspace_id',$w)->select('c.*')->limit(501)->get();$sample=$contacts->take(500);$valid=$sample->filter(fn($p)=>app(CadenceEmail::class)->address($p))->count();
  $add('contacts',$sample->count()>0,'Público cadastrado',$sample->count().' contato(s) consultado(s); '.$valid.' com e-mail válido. '.($contacts->count()>500?'Amostra limitada a 500.':''));
  if(!empty($s['whatsapp_enabled'])){
   $add('wa_mode',($s['whatsapp_delivery']??'simulation')==='automatic','WhatsApp após chamadas reais','A opção automática precisa estar selecionada no cartão Enviar WhatsApp.');
   $sender=DB::table('wa_senders')->where('workspace_id',$w)->find($s['whatsapp_sender_id']??0);
   $add('wa_sender',$sender?->status==='ONLINE','Remetente WhatsApp conectado','Situação registrada: '.($sender?->status??'não selecionado').'. Confira a conexão em Canais → WhatsApp; este diagnóstico não consulta o provedor.');
   if($sender?->provider==='twilio'){$t=DB::table('wa_templates')->where('workspace_id',$w)->find($s['whatsapp_real_template_id']??'');$add('wa_template',$t?->approval_status==='approved','Template oficial aprovado','Revise o template e suas variáveis antes de enviar.');}
  }else $add('wa_disabled',false,'WhatsApp desativado nesta cadência','Ative somente se este canal fizer parte do teste.');
  return response()->json(['campaign'=>['id'=>$c->id,'name'=>$c->name,'status'=>$c->status],'threshold'=>app(CadenceEmail::class)->threshold($s),'checks'=>$checks,'queues'=>$diagnostics,'email'=> $email?['enabled'=>(bool)$email->enabled,'revision'=>$email->revision,'delay_minutes'=>$email->delay_minutes,'subject'=>$email->subject,'body'=>$email->body]:['enabled'=>false,'revision'=>0,'delay_minutes'=>0,'subject'=>'Podemos conversar, {primeiro_nome}?','body'=>'Olá, {primeiro_nome}! Tentamos falar com você por telefone. Qual é o melhor horário para conversarmos?'],'transport'=>app(CadenceEmailTransport::class)->info(),'history'=>DB::table('voice_email_followups')->where('workspace_id',$w)->where('campaign_id',$id)->orderByDesc('created_at')->limit(50)->get(['id','destination','status','reason','created_at','due_at','submitted_at','accepted_at']),'totals'=>DB::table('voice_email_followups')->where('workspace_id',$w)->where('campaign_id',$id)->selectRaw('status, count(*) as total')->groupBy('status')->get(),'scope'=>'Conferência de registros e da conexão de e-mail no portal; não inicia chamadas nem mensagens. Aceito pelo serviço de envio não comprova entrega, leitura ou resposta.'])->header('Cache-Control','no-store, private');
 }
 public function save(Request $r,int $id){
  $c=$this->campaign($r,$id);$d=$r->validate(['enabled'=>'required|boolean','revision'=>'required|integer|min:0','delay_minutes'=>'required|integer|between:0,10080','subject'=>'required|string|max:200','body'=>'required|string|max:10000']);abort_if(preg_match('/[\r\n]/',$d['subject']),422,'O assunto deve ter apenas uma linha.');app(VoicePersonalization::class)->validate($d['subject']);app(VoicePersonalization::class)->validate($d['body']);
  DB::transaction(function()use($c,$d,$r){DB::table('voice_runtime')->where('id',1)->lockForUpdate()->firstOrFail();$current=DB::table('voice_campaigns')->find($c->id);abort_unless(in_array($current->status,['paused','draft']),422,'Pause a cadência antes de configurar o e-mail.');abort_if(DB::table('voice_outbound_calls')->where('campaign_id',$c->id)->whereNull('capacity_released_at')->exists(),409,'Conclua as chamadas antes de alterar.');abort_if(DB::table('voice_live_reservations')->where('campaign_id',$c->id)->whereIn('status',['reserved','calling','tabulation'])->exists()||DB::table('voice_email_followups')->where('campaign_id',$c->id)->where('status','submitting')->exists(),409,'Conclua os atendimentos e envios em processamento antes de alterar.');$old=DB::table('voice_email_settings')->where('campaign_id',$c->id)->first();abort_unless(($old?->revision??0)===$d['revision'],409,'A configuração mudou. Feche e abra novamente antes de editar.');$next=$d;$next['revision']++;DB::table('voice_email_settings')->updateOrInsert(['campaign_id'=>$c->id],$next+['workspace_id'=>$c->workspace_id,'created_at'=>$old?->created_at??now(),'updated_at'=>now()]);DB::table('voice_email_followups')->where('campaign_id',$c->id)->whereIn('status',['pending','blocked'])->update(['status'=>'cancelled','reason'=>'Configuração de e-mail alterada.','updated_at'=>now()]);app(VoiceLab::class)->audit($c->workspace_id,$r->user()->id,'cadence.email.configured',(string)$c->id,['enabled'=>$d['enabled'],'revision'=>$next['revision']]);});return $this->show($r,$id);
 }
 public function retry(Request $r,int $id,string $message){$c=$this->campaign($r,$id);app(CadenceEmail::class)->retry($c->workspace_id,$id,$message);return $this->show($r,$id);}
 public function unsubscribe(Request $r,string $id){abort_unless(DB::table('voice_email_followups')->where('id',$id)->whereNotNull('submitted_at')->exists(),404);if($r->isMethod('POST'))app(CadenceEmail::class)->unsubscribe($id);return response()->view('email-unsubscribe',['done'=>$r->isMethod('POST')])->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');}
}
